<script>
 import {onMount,tick} from 'svelte';
 import WindowControls from './WindowControls.svelte';
 import {gamesWindow,gamesCapabilities} from './games-tips-state.js';
 import {gamesProjection} from './games-library.js';
 import {gamesMenus} from './games-tips-menus.js';
 import {createGamesTipsNativeView} from './games-tips-native-view.js';
 import boardArt from './games-board.svg';
 import './games-tips.css';
 let {state: gamesState,profile,windowId,window:actualWindow=null,execute,registerView,available=true,active=true,controls={},store=null,chess=null}=$props();
 let root=$state(null),message=$state(''),draftName=$state('');let originalState,originalProfile,originalId,facade,retired=false;
 const id=$derived(windowId??actualWindow?.id),session=$derived(gamesWindow(gamesState,id)),cap=$derived(gamesCapabilities(profile)),projection=$derived(gamesProjection(store,chess,profile,session?.query??'')),groups=$derived(gamesMenus({state: gamesState,profile,windowId:id})),menu=$derived(groups.find(row=>row.id===session?.menu));
 const sections=[['home','Home'],['library','Library'],['recents','Retained Games'],['profile','Local Profile']];
 function current(){return !retired&&root?.isConnected===true&&gamesState===originalState&&profile===originalProfile&&id===originalId;}
 async function command(suffix,payload={}){if(!current()||!available||!active)return;const response=await execute(`games.${suffix}`,{windowId:id},payload);if(current())message=response?.status==='applied'?'':response?.error?.message??'The native action was not acknowledged.';return response;}
 async function menuAction(item){if(!item.enabled)return;await command(item.request.command.slice(6),item.request.payload);if(current()&&session.menu)await command('sheet',{menu:null});}
 function keyboard(event){if(!current()||!available||!active)return;if(event.key==='Escape'&&(session.sheet!=='none'||session.menu)){event.preventDefault();command('sheet',{sheet:'none',menu:null});}else if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='f'){event.preventDefault();command('focus',{controlId:'search'});}else if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='w'){event.preventDefault();command('window.close');}}
 onMount(()=>{originalState=gamesState;originalProfile=profile;originalId=id;facade=createGamesTipsNativeView({getRoot:()=>root,getState:()=>gamesState,getProfile:()=>profile,windowId:id,kind:'games',available:()=>current()&&available,tick});registerView?.(id,facade);return()=>{retired=true;facade.destroy();registerView?.(originalId,null,facade);};});
</script>
<section bind:this={root} class="native-guide games-native" class:classic={cap.classic} class:windows={cap.windows} class:golden={cap.golden} class:inactive={!active} data-profile={cap.era} aria-label={cap.label} role="region" tabindex="0" onkeydown={keyboard}>
 {#if session}
 <header class="guide-titlebar">{#if !cap.windows}<WindowControls {active} onclose={()=>command('window.close')} onminimize={controls.onminimize} onzoom={controls.onzoom} onfullscreen={controls.onfullscreen} fullScreen={controls.fullScreen}/>{/if}<strong>{cap.label}</strong><button data-games-control="help" aria-label="Games Help" onclick={()=>command('sheet',{sheet:'help'})}>?</button></header>
 <div class="guide-layout" inert={!available||!active||session.sheet!=='none'}>
 <aside class="guide-sidebar"><h1>Games</h1><p class="guide-kicker">Your local collection</p><nav aria-label="Games sections">{#each sections as [section,label]}<button data-games-control={`section:${section}`} aria-current={session.section===section?'page':undefined} onclick={()=>command('navigate',{section})}>{label}</button>{/each}</nav><div class="guide-sidebar-bottom"><span class="local-avatar" aria-hidden="true">{session.playerName.slice(0,1).toUpperCase()}</span><strong>{session.playerName}</strong><small>Local only · no online account</small></div></aside>
 <main class="guide-main" data-games-content><div class="guide-toolbar"><nav aria-label="Games menus">{#each groups.filter(row=>row.id!=='application') as group}<button data-games-control={`menu:${group.id}`} aria-expanded={session.menu===group.id} onclick={()=>command('sheet',{menu:session.menu===group.id?null:group.id})}>{group.label}</button>{/each}</nav><input type="search" data-games-control="search" aria-label="Search your games" placeholder="Search your games" value={session.query} oninput={event=>command('search',{query:event.currentTarget.value})}/></div>
 {#if menu}<div class="guide-menu" role="menu" aria-label={menu.label}>{#each menu.children as item}<button role="menuitem" disabled={!item.enabled} data-games-control={`item:${item.id}`} onclick={()=>menuAction(item)}>{item.checked?'✓ ':''}{item.label}<kbd>{item.shortcut??''}</kbd></button>{/each}</div>{/if}
 {#if !projection.available}<p role="alert">The original Store and Chess sources are unavailable. No substitute library or statistics are displayed.</p>
 {:else if session.section==='profile'}
 <h2>Your local profile</h2><p>A display name for this Games window, not a Game Center identity.</p><form onsubmit={event=>{event.preventDefault();command('profile',{name:draftName||session.playerName});}}><label>Display name<input data-games-control="player-name" maxlength="80" placeholder={session.playerName} bind:value={draftName}/></label><button class="guide-primary" data-games-control="save-profile" type="submit">Save Display Name</button></form><h3>Played here</h3><p>{projection.stats.scope}. Closing or resetting a Chess session removes its contribution; these are not lifetime statistics.</p><dl class="games-stats"><div><dt>Played games</dt><dd>{projection.stats.played}</dd></div><div><dt>Finished games</dt><dd>{projection.stats.finished}</dd></div><div><dt>White wins</dt><dd>{projection.stats.whiteWins}</dd></div><div><dt>Black wins</dt><dd>{projection.stats.blackWins}</dd></div><div><dt>Draws</dt><dd>{projection.stats.draws}</dd></div><div><dt>Played half-moves</dt><dd>{projection.stats.plies}</dd></div></dl>
 {:else}
 <h2>{session.section==='home'?'Ready when you are':session.section==='library'?'Your library':'Currently retained Chess games'}</h2>
 {#if session.section!=='recents'}
 {#if projection.showChess}<article class="games-feature"><img src={boardArt} alt="Authored illustration of a local chess board"/><div><span class="guide-kicker">BUNDLED LOCAL GAME</span><h3>Chess</h3><p>Share a board with another player. Real legal moves, genuine PGN and FEN documents. No online opponents.</p><button class="guide-primary" data-games-control="launch:chess" onclick={()=>command('launch',{appId:projection.chessAppId})}>Open Chess</button></div></article>{/if}
 <h3>Installed Store games</h3>{#if projection.installed.length}<div class="guide-card-grid">{#each projection.installed as game}<article class="guide-card"><h3>{game.name}</h3><p>Installed version {game.version}</p><button data-games-control={`launch:${game.appId}`} onclick={()=>command('launch',{appId:game.appId})}>Play</button></article>{/each}</div>{:else}<div class="guide-empty"><strong>No installed Store games</strong><p>The actual local Store catalog contains calculator packages, not games. Installing a utility does not add it to this library.</p></div>{/if}
 {/if}
 <h3>{session.section==='recents'?'Retained matches':'Continue a retained game'}</h3><p class="guide-muted">Canonical Chess sessions only. A fresh board is not counted as a played game; no play times or online activity are invented.</p>
 {#each projection.matches as match}<article class="games-match"><div><h4>{match.title}</h4><p>{match.moves.length} played half-moves · {match.result==='*'?'In progress':match.result==='1-0'?'White wins':match.result==='0-1'?'Black wins':'Draw'}</p>{#if match.moves.length}<p class="games-move-line">{match.moves.slice(-8).map(move=>move.san).join(' ')}</p>{/if}</div><div class="games-match-actions"><button class="guide-primary" data-games-control={`resume:${match.windowId}`} onclick={()=>command('resume',{chessWindowId:match.windowId})}>Show Board</button>{#each [['undo','Undo'],['flip','Flip'],['save','Save PGN'],['draw','Agree Draw'],['resign','Resign']] as [action,label]}<button data-games-control={`${action}:${match.windowId}`} disabled={action==='undo'&&!match.moves.length||['draw','resign'].includes(action)&&match.result!=='*'} onclick={()=>command('chess',{chessWindowId:match.windowId,action})}>{label}</button>{/each}</div></article>{:else}<p class="guide-empty">No retained Chess matches {session.query?'match this search.':'yet. Open Chess to start a real local game.'}</p>{/each}
 {/if}
 <p class="guide-qualification">{cap.disclosure}</p><p class="guide-status" role="status">{message}</p>
 </main></div>
 {#if session.sheet==='help'}<div class="guide-sheet" role="dialog" aria-modal="true" aria-label="Games Help"><h2>Play what is really here</h2><p>Library reads actual Store installations and the canonical Chess graph. Show Board focuses the original Chess window; Undo, Flip, Save PGN, Agree Draw and Resign execute its real typed controller commands.</p><p>The local profile is only a display name. There are no fabricated friends, leaderboards, achievements, subscriptions or Game Center sign-ins. Statistics cover retained games with at least one played move.</p><p>{cap.disclosure}</p><button data-games-control="dismiss-help" onclick={()=>command('sheet',{sheet:'none'})}>Done</button></div>{/if}
 {:else}<p role="alert">The original Games session is unavailable.</p>{/if}
</section>
